    if path == "/v1/projects":
        if method == "GET":
            data = store.load()
            return 200, {"projects": data.get("projects", [])}
        if method == "POST":
            data = _json_body(body)
            title = str(data.get("title", "")).strip()
            slug = str(data.get("slug", "")).strip()
            if not title or not slug:
                return 400, {"error": "title and slug are required"}

            store_data = store.load()
            if any(p.get("slug") == slug for p in store_data.get("projects", [])):
                return 409, {"error": "slug already exists"}

            project = {
                "id": new_id("proj"),
                "title": title,
                "slug": slug,
                "description": data.get("description", ""),
                "status": "draft",
                "created_at": now_iso(),
                "updated_at": now_iso(),
            }
            store_data.get("projects", []).append(project)
            store.save(store_data)
            return 201, project

        return 405, {"error": "method not allowed"}

    # Projects resource
    if path.startswith("/v1/projects/"):
        parts = [p for p in path.split("/") if p]
        if len(parts) < 3:
            return 404, {"error": "not found"}

        project_id = parts[2]

        # GET /v1/projects/:id
        if len(parts) == 3 and method == "GET":
            data = store.load()
            for proj in data.get("projects", []):
                if proj.get("id") == project_id:
                    return 200, proj
            return 404, {"error": "project not found"}

        # POST /v1/projects/:id/builds
        if len(parts) == 4 and parts[3] == "builds" and method == "POST":
            data = store.load()
            if not any(p.get("id") == project_id for p in data.get("projects", [])):
                return 404, {"error": "project not found"}

            build = {
                "id": new_id("build"),
                "project_id": project_id,
                "status": "pending",
                "created_at": now_iso(),
            }
            data.setdefault("builds", []).append(build)
            store.save(data)
            return 202, build

        return 404, {"error": "not found"}

    # Builds resource
    if path.startswith("/v1/builds/"):
        parts = [p for p in path.split("/") if p]
        if len(parts) != 3 or method != "GET":
            return 404, {"error": "not found"}

        build_id = parts[2]
        data = store.load()
        for build in data.get("builds", []):
            if build.get("id") == build_id:
                return 200, build
        return 404, {"error": "build not found"}

    # Email capture
    if path == "/v1/emails":
        if method == "POST":
            req_data = _json_body(body)
            email = str(req_data.get("email", "")).strip()
            if not email or not _EMAIL_RE.match(email):
                return 422, {"error": "invalid email address"}

            return 201, {
                "success": True,
                "email": email,
                "message": "email captured successfully",
            }
        return 405, {"error": "method not allowed"}

    return 404, {"error": "not found"}

