                {"id": 3, "name": "Pro", "price": 29},
                {"id": 4, "name": "Elite", "price": 99},
            ],
        },
        "created_at": now_iso(),
        "updated_at": now_iso(),
    }
    data["projects"].append(project)
    store.save(data)
    return project


