"""Request router for the NeuralBook platform API."""

from __future__ import annotations

import json
import re
from pathlib import Path
from typing import Any, Dict, Tuple

from .core import (
    Store,
    capture_email,
    create_build,
    create_project,
    get_build,
    get_project,
    list_artifacts_for_build,
    list_projects,
    update_project,
)

_EMAIL_RE = re.compile(r"^[^@\s]+@[^@\s]+\.[^@\s]+$")

VERSION = "1.0.0"


def _json_body(raw: bytes) -> Dict[str, Any]:
    if not raw:
        return {}
    try:
        return json.loads(raw.decode("utf-8"))  # type: ignore[return-value]
    except (json.JSONDecodeError, UnicodeDecodeError):
        return {}


def route_request(
    method: str,
    path: str,
    body: bytes,
    store_path: Path,
) -> Tuple[int, Dict[str, Any]]:
    """Route an HTTP request to the appropriate handler.

    Args:
        method: HTTP verb (GET, POST, PUT, …)
        path: URL path, may include query string
        body: Raw request body bytes
        store_path: Filesystem path to the JSON data store

    Returns:
        (http_status_code, response_body_dict)
    """
    store = Store(store_path)
    email_path = store_path.parent / "captured_emails.json"

    # Strip query string for routing
    path = path.split("?")[0]

    # Root
    if path == "/" and method == "GET":
        return 200, {
            "message": "NeuralBook Platform API",
            "version": VERSION,
            "docs": "/docs",
