        """Compute current seal without applying it."""
        section_hashes = {s["id"]: s["hash"] for s in self.content}
        rh = root_hash(self.content)
        return {
            "algorithm": "sha256",
            "root_hash": rh,
            "section_hashes": section_hashes,
            "sealed_at": None,
        }

